input.command:
for f in more_itertools/*.pyi; do python3 -c "import ast,sys; ast.parse(open(sys.argv[1]).read()); print('parsed', sys.argv[1])" "$f" || echo "PARSE FAIL $f"; done; echo "--- stub vs source public names"; python3 - <<'EOF'
import ast
def names(path):
    t = ast.parse(open(path).read())
    return {n.name for n in t.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))} | {tg.id for n in t.body if isinstance(n,ast.Assign) for tg in n.targets if isinstance(tg,ast.Name)}
for mod in ["more","recipes"]:
    src = names(f"more_itertools/{mod}.py"); stub = names(f"more_itertools/{mod}.pyi")
    print(mod, "in source not stub:", sorted(src-stub)[:50])
    print(mod, "in stub not source:", sorted(stub-src)[:50])
EOF

